export function areaMovements(id,seated=false){const ids=routines[id].movements;return [...new Set(ids.map(id=>seated?(seatMap[id]||id):id))];}
export function routineSteps(id,minutes,moveSeconds=30,seated=false){
 const seconds=[15,30,60].includes(moveSeconds)?moveSeconds:30,target=Math.round(minutes*60),ids=areaMovements(id,seated),blocks=ids.map(id=>exercises[id].bilateral?[{id,side:'left'},{id,side:'right'}]:[{id,side:''}]);
 const out=[];let remaining=target,round=1;
 while(remaining>0&&out.length<120){
  const capacity=Math.floor(remaining/seconds),dp=Array(capacity+1).fill(null);dp[0]={score:0,chosen:[]};
  blocks.forEach((block,i)=>{const cost=block.length,weight=2**(blocks.length-i);for(let n=capacity;n>=cost;n--){const prev=dp[n-cost];if(prev){const score=prev.score+weight;if(!dp[n]||score>dp[n].score)dp[n]={score,chosen:[...prev.chosen,i]};}}});
  let n=capacity;while(n>0&&!dp[n])n--;
  if(n===0){const half=remaining/2;out.push(...blocks[0].map(s=>({...s,seconds:half,round})));remaining=0;}
  else{for(const i of dp[n].chosen)out.push(...blocks[i].map(s=>({...s,seconds,round})));remaining-=n*seconds;}
  round++;
 }
 return out;
}
export function planSummary(id,minutes,moveSeconds=30,prep=5,seated=false){const slots=routineSteps(id,minutes,moveSeconds,seated),work=slots.reduce((s,x)=>s+x.seconds,0);return {slots,work,prep:slots.length*prep,total:work+slots.length*prep,unique:new Set(slots.map(s=>s.id)).size,rounds:Math.max(...slots.map(s=>s.round))};}
export function makeTimeline(id,minutes,prep=5,moveSeconds=30,seated=false){return timelineForSteps(routineSteps(id,minutes,moveSeconds,seated),prep);}
export function timelineForSteps(slots,prep=5){return slots.flatMap((s,slot)=>{const common={...s,slot,timed:true};return [...(prep>0?[{...common,kind:'prepare',label:'Get into position',seconds:prep}]:[]),{...common,kind:'work',label:exercises[s.id].continuous?'Move slowly':'Hold comfortably',seconds:s.seconds||30,rep:1,part:0}];});}
export function legacyTimelineForSteps(slots,prep=10){const out=[];slots.forEach((step,slot)=>{const e=exercises[step.id],common={...step,slot};out.push({...common,kind:'prepare',label:'Get into position',seconds:prep});for(let rep=1;rep<=e.reps;rep++)for(let part=0;part<e.parts.length;part++){const [label,seconds]=e.parts[part];out.push({...common,kind:'work',label,seconds,rep,part});}const work=e.reps*e.parts.reduce((s,p)=>s+p[1],0),rest=75-prep-work;if(rest>0)out.push({...common,kind:'rest',label:'Relax and reset',seconds:rest});});return out;}
